    M -->|"agree"| S["score SETTLES<br/>agreeing verifiers get PAID<br/>verdicts Ed25519-SIGNED"]:::ok
    M -->|"dissent"| N["no score · no pay<br/>outliers land in the<br/>deviation feed"]:::deny
    classDef own fill:#141e2e,stroke:#3B82F6,stroke-width:2px,color:#e4ecf4
