    rgba(10, 13, 22, 0.45);
  border: 1px solid rgba(255,255,255,0.07);
  box-shadow: 0 8px 32px rgba(0,0,0,0.42), inset 0 1px 0 rgba(255,255,255,0.04);
  overflow-x: auto;
  text-align: center;
  font-family: 'Inter', system-ui, sans-serif;
  color: rgba(176, 190, 197, 0.65);
  font-size: 12px;
  letter-spacing: 0.08em;
}
/* Pre-render placeholder: shown before mermaid swaps in the SVG */
.bl-content :deep(.bl-mermaid:not([data-processed="true"]))::before {
  content: "rendering diagram…";
  display: block;
  font-family: 'JetBrains Mono', var(--mono), monospace;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(var(--nc-primary-rgb), 0.55);
  padding: 2rem 0;
}
.bl-content :deep(.bl-mermaid[data-processed="true"]) {
  cursor: zoom-in;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.bl-content :deep(.bl-mermaid[data-processed="true"]:hover) {
  border-color: rgba(var(--nc-primary-rgb), 0.4);
  box-shadow: 0 12px 40px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06);
}
.bl-content :deep(.bl-mermaid[data-processed="true"])::after {
  content: "click to enlarge";
  position: absolute;
  bottom: 0.55rem; right: 0.85rem;
  font-family: 'JetBrains Mono', var(--mono), monospace;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(var(--nc-primary-rgb), 0.45);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}
.bl-content :deep(.bl-mermaid[data-processed="true"]:hover)::after {
  opacity: 1;
}
.bl-content :deep(.bl-mermaid svg) {
  max-width: 100%;
  height: auto;
  display: inline-block;
}
.bl-content :deep(.bl-mermaid .label) {
  font-family: 'Inter', system-ui, sans-serif !important;
}

/* ── FIGURES — proper image framing + click-to-enlarge ─────────── */
.bl-content :deep(figure) {
  margin: 2.2rem 0;
  padding: 0;
  position: relative;
}
.bl-content :deep(figure img) {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.07);
  box-shadow: 0 8px 32px rgba(0,0,0,0.42);
  cursor: zoom-in;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}
.bl-content :deep(figure img:hover) {
  border-color: rgba(var(--nc-primary-rgb), 0.35);
  box-shadow: 0 12px 40px rgba(0,0,0,0.55);
}

/* ── TALL FRAMES ────────────────────────────────────────────────────────
   A whole conversation shot end to end is 6,000px of image. Left to run at
   column width it becomes a wall nobody scrolls past, and cropping it would
   undo the entire point of shooting it whole. So it scrolls inside its own
   frame at full width, and the lightbox is still one click away. */
.bl-content :deep(.bl-tallbox) {
  max-height: 70vh;
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 12px;
  border: 1px solid rgba(255,255,255,0.07);
  box-shadow: 0 8px 32px rgba(0,0,0,0.42);
  background: rgba(0,0,0,0.25);
}
.bl-content :deep(.bl-tallbox img) {
  border: 0;
  border-radius: 0;
  box-shadow: none;
  margin: 0;
}
.bl-content :deep(.bl-tallbox)::-webkit-scrollbar { width: 8px; }
.bl-content :deep(.bl-tallbox)::-webkit-scrollbar-thumb {
  background: rgba(var(--nc-primary-rgb), 0.30); border-radius: 4px;
}
/* the hover hint is anchored to the figure, and inside a scroll box it would
   ride over the image as the reader scrolls — pin it to the figure instead */
.bl-content :deep(figure.bl-tall)::after { content: "scroll inside \2014 click to enlarge"; }
.bl-content :deep(figure)::after {
  content: "click to enlarge";
  position: absolute;
  top: 0.65rem; right: 0.85rem;
  font-family: 'JetBrains Mono', var(--mono), monospace;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 0.25rem 0.5rem;
  border-radius: 5px;
  background: rgba(10, 13, 22, 0.65);
  border: 1px solid rgba(var(--nc-primary-rgb), 0.25);
  color: rgba(var(--nc-primary-rgb), 0.7);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}
.bl-content :deep(figure:hover)::after {
  opacity: 1;
}
.bl-content :deep(figcaption) {
  font-size: 13.5px;
  line-height: 1.65;
  color: rgba(148, 163, 184, 0.75);
  font-style: italic;
  margin-top: 0.9rem;
  padding: 0 0.5rem;
  text-align: center;
}
.bl-content :deep(figcaption code) {
  font-style: normal;
}

/* ── SCREENSHOT CAROUSEL (§TOURBLOG) — one window, side-scrollable ── */
.bl-content :deep(.bl-carousel) {
  display: flex;
  gap: 18px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding: 6px 2px 14px;
  margin: 2rem 0 0.4rem;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(100, 116, 139, 0.5) transparent;
}
.bl-content :deep(.bl-carousel)::-webkit-scrollbar { height: 8px; }
.bl-content :deep(.bl-carousel)::-webkit-scrollbar-thumb {
  background: rgba(100, 116, 139, 0.45);
  border-radius: 4px;
}
.bl-content :deep(.bl-carousel figure) {
  flex: 0 0 min(78%, 860px);
  scroll-snap-align: center;
  margin: 0;
  padding: 0;
}
.bl-content :deep(.bl-carousel figure img) {
  width: 100%;
  border-radius: 10px;
  border: 1px solid rgba(100, 116, 139, 0.35);
  cursor: zoom-in;
}
.bl-content :deep(.bl-carousel figcaption) {
  font-size: 12.5px;
  margin-top: 0.55rem;
  padding: 0 0.2rem;
}
/* Whole pages, each in full (journal 52): a frame of fixed height that scrolls down the page; a phone page keeps a
   phone's width */
.bl-content :deep(.bl-carousel--pages figure) {
  flex: 0 0 min(88%, 940px);
}
.bl-content :deep(.bl-page-frame) {
  max-height: min(70vh, 720px);
  overflow-y: auto;
  overscroll-behavior: contain;
  border-radius: 10px;
  border: 1px solid rgba(100, 116, 139, 0.35);
  scrollbar-width: thin;
  scrollbar-color: rgba(100, 116, 139, 0.5) transparent;
}
/* a carousel and a page frame scroll, so each takes focus (journal 52, axe scrollable-region-focusable): show where it is */
.bl-content :deep(.bl-carousel:focus-visible),
.bl-content :deep(.bl-page-frame:focus-visible) {
  outline: 2px solid rgba(127, 233, 200, 0.85);
  outline-offset: 3px;
}
.bl-content :deep(.bl-page-frame--phone) {
  max-width: 400px;
  margin: 0 auto;
}
.bl-content :deep(.bl-page-frame img) {
  display: block;
  border: 0;
  border-radius: 0;
}
.bl-content :deep(.bl-carousel-hint) {
  font-size: 12px;
  color: rgba(148, 163, 184, 0.8);
  text-align: center;
  margin: 0 0 1.6rem;
  font-style: italic;
}
.bl-content :deep(.bl-carousel-wrap) {
  position: relative;
}
.bl-content :deep(.bl-car-btn) {
  position: absolute;
  top: 42%;
  transform: translateY(-50%);
  z-index: 5;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid rgba(148, 163, 184, 0.4);
  background: rgba(10, 15, 25, 0.82);
  color: #e2e8f0;
  font-size: 26px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.bl-content :deep(.bl-car-btn:hover) {
  background: rgba(30, 41, 59, 0.95);
  border-color: rgba(203, 213, 225, 0.7);
}
.bl-content :deep(.bl-car-prev) { left: -8px; }
.bl-content :deep(.bl-car-next) { right: -8px; }
/* The whole console, section by section (journal 52): each section folds, so the text after it stays near the top,
   and a section's pages load only once it is opened */
.bl-content :deep(details.bl-gallery) {
  margin: 0.75rem 0;
  border: 1px solid rgba(100, 116, 139, 0.35);
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.18);
}
.bl-content :deep(details.bl-gallery[open]) {
  border-color: rgba(var(--nc-primary-rgb), 0.35);
}
.bl-content :deep(details.bl-gallery > summary) {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.3rem 0.9rem;
  padding: 0.85rem 1.1rem;
  cursor: pointer;
  list-style: none;
  user-select: none;
}
.bl-content :deep(details.bl-gallery > summary::-webkit-details-marker) { display: none; }
.bl-content :deep(details.bl-gallery > summary)::before {
  content: "\203A";
  display: inline-block;
