  color: rgba(var(--nc-primary-rgb), 0.85);
  transition: transform 0.15s ease;
}
.bl-content :deep(details.bl-gallery[open] > summary)::before { transform: rotate(90deg); }
.bl-content :deep(.bl-gal-head) {
