}
.bl-content :deep(details.bl-gallery > .bl-carousel-wrap) { margin: 0 1rem; }
.bl-content :deep(details.bl-gallery .bl-carousel) { margin-top: 0.2rem; }
.bl-content :deep(details.bl-gallery .bl-carousel-hint) { margin-bottom: 0.9rem; }
.bl-content :deep(.bl-gal-n) {
  font-style: normal;
  white-space: nowrap;
  margin-left: 0.35rem;
  color: rgba(148, 163, 184, 0.6);
}

/* Lightbox gallery navigation (§TOURBLOG v2) */
.bl-lightbox-nav {
  position: fixed;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: 54px;
  height: 54px;
  border-radius: 50%;
