}

/* ── LIGHTBOX (mermaid + figure images) ─────────────────────────── */
.bl-lightbox {
  position: fixed;
  inset: 0;
  z-index: 10002;
  background: rgba(6, 8, 16, 0.88);
  backdrop-filter: blur(8px) saturate(120%);
  -webkit-backdrop-filter: blur(8px) saturate(120%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4rem 2rem 2rem;
  animation: bl-lightbox-fade 0.22s ease-out;
}
@keyframes bl-lightbox-fade {
  from { opacity: 0; backdrop-filter: blur(0px); }
  to   { opacity: 1; backdrop-filter: blur(8px) saturate(120%); }
}
.bl-lightbox-stage {
  width: min(96vw, 1800px);
  max-height: calc(100vh - 8rem);
  overflow: auto;
  padding: 2rem;
  background: rgba(15, 18, 28, 0.7);
  border: 1px solid rgba(var(--nc-primary-rgb), 0.4);
  border-radius: 18px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.6),
              0 0 0 1px rgba(var(--nc-primary-rgb), 0.18) inset;
  cursor: default;
}
.bl-lightbox-stage-mermaid svg {
  width: 100% !important;
  height: auto !important;
  max-height: none !important;
  display: block;
  margin: 0 auto;
}
.bl-lightbox-stage-image {
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
}
.bl-lightbox-stage-image img.bl-lightbox-tall {
  max-height: none;
  width: min(100%, 1440px);
}
.bl-lightbox-stage-image img {
  max-width: 100%;
  max-height: calc(100vh - 14rem);
  width: auto;
  height: auto;
  border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.06);
  display: block;
}
.bl-lightbox-caption {
  font-size: 13.5px;
  line-height: 1.6;
  color: rgba(148, 163, 184, 0.85);
  font-style: italic;
  text-align: center;
  max-width: 880px;
  margin: 0;
  padding: 0 1rem;
}
.bl-lightbox-caption :deep(code) {
  font-style: normal;
  background: rgba(var(--nc-primary-rgb),0.06);
  border: 1px solid rgba(var(--nc-primary-rgb),0.1);
  padding: 2px 6px;
  border-radius: 3px;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 12px;
}
.bl-lightbox-close {
  position: absolute;
  top: 1.25rem;
  right: 1.5rem;
  background: rgba(15, 18, 28, 0.85);
  border: 1px solid rgba(var(--nc-primary-rgb), 0.4);
  color: #e4ecf4;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  cursor: pointer;
  font-size: 1.4rem;
  font-weight: 400;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  z-index: 1;
}
.bl-lightbox-close:hover {
  border-color: rgba(220, 38, 38, 0.55);
  background: rgba(42, 14, 14, 0.85);
  color: #fecaca;
  transform: scale(1.05);
}
.bl-lightbox-hint {
  position: absolute;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.78rem;
  letter-spacing: 0.05em;
  color: rgba(180, 188, 200, 0.7);
}
.bl-lightbox-hint kbd {
  background: rgba(var(--nc-primary-rgb), 0.18);
  border: 1px solid rgba(var(--nc-primary-rgb), 0.4);
  border-radius: 5px;
  padding: 0.15rem 0.4rem;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 0.72rem;
  color: #e4ecf4;
  margin: 0 0.2rem;
}
@media (max-width: 768px) {
  .bl-lightbox { padding: 3rem 0.5rem 1rem; }
  .bl-lightbox-stage { padding: 1rem; }
}

/* ── TABLES (markdown-style, even though blog content is inline HTML) ── */
.bl-content :deep(table) {
